import os
os.environ["HF_ENDPOINT"] = "https://hf-mirror.com"

import json
import sys
from datasets import load_dataset

output_dir = "/root/autodl-tmp/data/training"
target_n = 5000

def try_wildchat():
    print("Trying WildChat-1M...", flush=True)
    try:
        ds = load_dataset("allenai/WildChat-1M", split="train", streaming=True)
        results = []
        seen = 0
        for ex in ds:
            seen += 1
            if seen % 10000 == 0:
                print(f"  Scanned {seen}, collected {len(results)}", flush=True)

            conv = ex.get("conversation", [])
            if not conv:
                continue

            # Filter: need >= 10 messages (5+ user turns)
            if len(conv) < 10:
                continue

            # Clean: remove system messages, ensure proper format
            cleaned = []
            for msg in conv:
                role = msg.get("role", "")
                content = msg.get("content", "")
                if not content or not content.strip():
                    continue
                if role == "system":
                    # Merge system into first user message later
                    if not cleaned:
                        cleaned.append({"role": "user", "content": content.strip()})
                    continue
                if role in ("user", "assistant"):
                    # If same role as previous, merge
                    if cleaned and cleaned[-1]["role"] == role:
                        cleaned[-1]["content"] += "\n" + content.strip()
                    else:
                        cleaned.append({"role": role, "content": content.strip()})

            # Must start with user
            if not cleaned or cleaned[0]["role"] != "user":
                continue

            # Count user turns
            user_turns = sum(1 for m in cleaned if m["role"] == "user")
            if user_turns < 5:
                continue
            if user_turns > 25:
                # Trim to ~25 user turns
                count = 0
                trim_idx = len(cleaned)
                for i, m in enumerate(cleaned):
                    if m["role"] == "user":
                        count += 1
                        if count > 25:
                            trim_idx = i
                            break
                cleaned = cleaned[:trim_idx]
                user_turns = sum(1 for m in cleaned if m["role"] == "user")

            results.append({
                "conversation": cleaned,
                "n_turns": user_turns,
                "source": "wildchat"
            })

            if len(results) >= target_n:
                break

        return results
    except Exception as e:
        print(f"WildChat failed: {e}", flush=True)
        return []

def try_ultrachat():
    print("Trying UltraChat...", flush=True)
    try:
        ds = load_dataset("stingning/ultrachat", split="train", streaming=True)
        results = []
        seen = 0
        for ex in ds:
            seen += 1
            if seen % 10000 == 0:
                print(f"  Scanned {seen}, collected {len(results)}", flush=True)

            # UltraChat format: list of strings alternating user/assistant
            data = ex.get("data", [])
            if not data or len(data) < 10:
                continue

            cleaned = []
            for i, text in enumerate(data):
                if not text or not text.strip():
                    continue
                role = "user" if i % 2 == 0 else "assistant"
                cleaned.append({"role": role, "content": text.strip()})

            user_turns = sum(1 for m in cleaned if m["role"] == "user")
            if user_turns < 5:
                continue

            if user_turns > 25:
                count = 0
                trim_idx = len(cleaned)
                for i, m in enumerate(cleaned):
                    if m["role"] == "user":
                        count += 1
                        if count > 25:
                            trim_idx = i
                            break
                cleaned = cleaned[:trim_idx]
                user_turns = sum(1 for m in cleaned if m["role"] == "user")

            results.append({
                "conversation": cleaned,
                "n_turns": user_turns,
                "source": "ultrachat"
            })

            if len(results) >= target_n:
                break

        return results
    except Exception as e:
        print(f"UltraChat failed: {e}", flush=True)
        return []

# Try in priority order
results = try_wildchat()
if len(results) < target_n:
    print(f"WildChat got {len(results)}, trying UltraChat for remaining...", flush=True)
    remaining = target_n - len(results)
    ultra_results = try_ultrachat()
    results.extend(ultra_results[:remaining])

if len(results) < target_n:
    print(f"WARNING: Only got {len(results)} samples total (target: {target_n})", flush=True)

print(f"\nTotal samples: {len(results)}", flush=True)

# Save
out_path = os.path.join(output_dir, "train_5k.json")
with open(out_path, "w", encoding="utf-8") as f:
    json.dump(results, f, ensure_ascii=False)
print(f"Saved to {out_path}", flush=True)
print(f"File size: {os.path.getsize(out_path) / 1024 / 1024:.1f} MB", flush=True)
PYEOF
echo "Script written."
